#!/usr/bin/env bash
# ini-sections.sh FILE : section names in order of first appearance
[ $# -eq 1 ] && [ -r "$1" ] || { echo "usage: ini-sections.sh FILE" >&2; exit 2; }
awk '/^[ \t]*\[/ { s = $0; sub(/^[ \t]*\[/, "", s); sub(/\][ \t]*$/, "", s); if (!(s in seen)) { seen[s] = 1; print s } }' "$1"

